INSERT INTO [dbo].[FAQs] ([FaqID], [Category], [Question], [Answer], [IsPublished], [CreatedDate]) VALUES
(1, N'Account', N'How do I register an account?', N'Click Register and complete the sign-up form.', 1, CONVERT(DATETIME2, '2025-01-06 00:00:00', 120)),
(2, N'Enrollment', N'How do I reset my password?', N'Use the Forgot Password link on the login page.', 1, CONVERT(DATETIME2, '2025-01-11 00:00:00', 120)),
(3, N'Assessment', N'How can I enroll in a course?', N'Open a course and click the Enroll button.', 1, CONVERT(DATETIME2, '2025-01-16 00:00:00', 120)),
(4, N'Technical', N'Can I retake an assessment?', N'Yes, if the instructor allows multiple attempts.', 1, CONVERT(DATETIME2, '2025-01-21 00:00:00', 120)),
(5, N'Support', N'Why is my lesson not loading?', N'Check your internet connection and try again.', 1, CONVERT(DATETIME2, '2025-01-26 00:00:00', 120)),
